 */
function buildDefensePrefixRules() {
  if (ruleOptionsEnable.AdBlock === false) return [...prefixRules];
  const defense = [
    'RULE-SET,defense-exceptions,直连',
    'RULE-SET,avenue-ads,AdBlock',
    ...(ruleOptionsEnable.完整防线 !== false ? ['RULE-SET,adrules,AdBlock'] : []),
